#!/bin/bash
# SRV-04: encrypted backup of the bot's state, pulled from the VPS.
#
# The archive is encrypted ON THE ADMIN MACHINE as it streams through
# the pipe: the VPS never stores ciphertext and never sees the
# passphrase. Passphrase lives in ~/.config/oflux-backup/passphrase
# (0600, generated by `init`), backups land in ~/Backups/oflux-bot.
#
# Usage:
#   backup_registry.sh init            generate passphrase + backup dir
#   backup_registry.sh pull            fetch, encrypt, verify, prune, stamp
#   backup_registry.sh verify <file>   list archive contents (decrypted)
#   backup_registry.sh drill [file]    restore to a scratch dir on the VPS
#                                      and reissue links from it (read-only)
set -euo pipefail

REPO="$(cd "$(dirname "$0")/.." && pwd)"
VPS="${OFLUX_VPS:-root@159.194.227.248}"
BOT_DIR="/root/.config/oflux-bot"
KEY_DIR="${HOME}/.config/oflux-backup"
PASSPHRASE_FILE="${KEY_DIR}/passphrase"
BACKUP_DIR="${HOME}/Backups/oflux-bot"
KEEP=14
FILES="bot.yaml servers.yaml users.json bot_users.json ya-cookies.txt"

enc() { openssl enc -aes-256-cbc -pbkdf2 -iter 200000 -salt -pass file:"$PASSPHRASE_FILE" "$@"; }
dec() { openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -salt -pass file:"$PASSPHRASE_FILE" "$@"; }

require_key() {
    if [ ! -f "$PASSPHRASE_FILE" ]; then
        echo "passphrase not found: $PASSPHRASE_FILE (run: $0 init)" >&2
        exit 1
    fi
}

cmd_init() {
    mkdir -p "$KEY_DIR" "$BACKUP_DIR"
    chmod 700 "$KEY_DIR"
    if [ -f "$PASSPHRASE_FILE" ]; then
        echo "passphrase already exists: $PASSPHRASE_FILE"
    else
        openssl rand -base64 48 | tr -d '\n' > "$PASSPHRASE_FILE"
        chmod 600 "$PASSPHRASE_FILE"
        echo "passphrase generated: $PASSPHRASE_FILE"
    fi
    echo "backup dir: $BACKUP_DIR"
    echo "ВНИМАНИЕ: без этого файла бэкапы не расшифровать — храни копию вне этого Mac."
}

latest_archive() {
    ls -1t "$BACKUP_DIR"/oflux-bot-*.tar.gz.enc 2>/dev/null | head -1
}

cmd_pull() {
    require_key
    mkdir -p "$BACKUP_DIR"
    local stamp out
    stamp="$(date +%Y%m%d-%H%M%S)"
    out="${BACKUP_DIR}/oflux-bot-${stamp}.tar.gz.enc"
    ssh "$VPS" "tar -czf - -C $BOT_DIR $FILES" | enc -out "${out}.tmp"
    chmod 600 "${out}.tmp"
    dec -in "${out}.tmp" | tar -tzf - >/dev/null   # roundtrip check
    mv "${out}.tmp" "$out"
    ssh "$VPS" "touch $BOT_DIR/.last-backup && chmod 600 $BOT_DIR/.last-backup"
    local old
    old="$(ls -1t "$BACKUP_DIR"/oflux-bot-*.tar.gz.enc | tail -n +$((KEEP + 1)) || true)"
    [ -n "$old" ] && rm -f $old
    echo "backup ok: $out ($(du -h "$out" | cut -f1))"
}

cmd_verify() {
    require_key
    local archive="${1:-$(latest_archive)}"
    [ -n "$archive" ] || { echo "нет архивов в $BACKUP_DIR" >&2; exit 1; }
    echo "archive: $archive"
    dec -in "$archive" | tar -tzvf -
}

cmd_drill() {
    require_key
    local archive="${1:-$(latest_archive)}"
    [ -n "$archive" ] || { echo "нет архивов в $BACKUP_DIR" >&2; exit 1; }
    local tmp
    tmp="$(mktemp -d)"
    trap 'rm -rf "$tmp"' EXIT
    dec -in "$archive" | tar -xzf - -C "$tmp"
    ssh "$VPS" "rm -rf /tmp/oflux-restore-drill && mkdir -p /tmp/oflux-restore-drill && chmod 700 /tmp/oflux-restore-drill"
    scp -q -p "$tmp"/* "$VPS:/tmp/oflux-restore-drill/"
    # read-only drill on the VPS: restored config must reissue real links
    ssh "$VPS" "cd /root/openflux_vpn && OFLUX_BOT_CONFIG_DIR=/tmp/oflux-restore-drill .venv/bin/python scripts/restore_drill.py"
    ssh "$VPS" "rm -rf /tmp/oflux-restore-drill"
}

case "${1:-}" in
    init)   cmd_init ;;
    pull)   cmd_pull ;;
    verify) shift; cmd_verify "$@" ;;
    drill)  shift; cmd_drill "$@" ;;
    *)
        echo "usage: $0 init | pull | verify [file] | drill [file]" >&2
        exit 2
        ;;
esac
